mapper.select:
select *
from batch.dead_letter_task
where tenant_id = #{tenantId}
  and id = #{id}

mapper.update:
update batch.dead_letter_task
set replay_status = #{targetStatus},
    updated_at = current_timestamp
where tenant_id = #{tenantId}
  and id = #{id}
  and replay_status = #{expectedStatus}

mapper.select:
select count(*) from batch.dead_letter_task
where replay_status in
#{s}

select dead_letter.* from batch.dead_letter_task dead_letter where dead_letter.replay_status in
#{status}
and dead_letter.error_class = 'SYSTEM' and dead_letter.next_replay_at is not null and dead_letter.next_replay_at <= current_timestamp and dead_letter.replay_count < dead_letter.max_replay_count and not exists ( select 1 from batch.job_partition partition join batch.job_instance instance on instance.tenant_id = partition.tenant_id and instance.id = partition.job_instance_id left join lateral ( select workflow_run.id, workflow_run.run_status from batch.workflow_run workflow_run join batch.workflow_node_run node_run on node_run.workflow_run_id = workflow_run.id and node_run.job_instance_id = instance.id where workflow_run.tenant_id = dead_letter.tenant_id and workflow_run.related_job_instance_id is null order by workflow_run.id desc limit 1 ) latest_workflow on true where dead_letter.source_type = 'JOB_PARTITION' and partition.tenant_id = dead_letter.tenant_id and partition.id = dead_letter.source_id and (latest_workflow.id is null or latest_workflow.run_status in ('CREATED', 'RUNNING', 'PAUSED')) and ( instance.instance_status = 'PAUSED' or (instance.instance_status in ('CREATED', 'WAITING', 'READY', 'RUNNING') and latest_workflow.run_status = 'PAUSED') ) ) order by dead_letter.next_replay_at asc, dead_letter.id asc limit #{batchSize}
